+        for (int offset = startOffset + 1; offset < endOffset - 1; offset++) {
+            var c = doc[offset];
+            if (escape) {
+                switch (c) {
+                    case '"', '\\', '/' -> {}
+                    case 'b' -> c = '\b';
+                    case 'f' -> c = '\f';
+                    case 'n' -> c = '\n';
+                    case 'r' -> c = '\r';
+                    case 't' -> c = '\t';
+                    case 'u' -> {
+                        // Will not throw NFE, document parse already validated input
+                        c = (char) Integer.parseInt(new String(doc, offset + 1, 4), 16);
+                        offset += 4;
+                    }
+                }
+                escape = false;
+            } else if (c == '\\') {
+                escape = true;
+                continue;
+            }
+            sb.append(c);
+        }
+        return sb.toString();
+    }
