+                    sb.append('b');
+                } else if (c == '\f') {
+                    sb.append('f');
+                } else if (c == '\n') {
+                    sb.append('n');
+                } else if (c == '\r') {
+                    sb.append('r');
+                } else if (c == '\t') {
+                    sb.append('t');
