+            int oDepth = 0;
+            int values = 0;
+            boolean inString = false;
+            while (offset > 0) {
+                var c = doc[offset];
+                if (inString) {
+                    if (c == '"' && doc[offset - 1] != '\\') {
+                        inString = false;
+                    }
+                } else {
+                    if (c == '[') {
+                        aDepth++;
+                    } else if (c == ']') {
+                        aDepth--;
+                    } else if (c == '{') {
+                        oDepth++;
+                    } else if (c == '}') {
+                        oDepth--;
+                    } else if (c == ',' && aDepth == 0 && oDepth == 0) {
+                        values++;
+                    } else if (c == '"') {
+                        inString = true;
+                    } else if (c == '\n') {
+                        addLine(offset);
+                    }
+                    if (aDepth > 0) {
