+            boolean inString = false;
+            // Move to parent offset
+            while (offset > 0) {
+                var c = doc[offset];
+                if (inString) {
+                    if (c == '"' && doc[offset - 1] != '\\') {
+                        inString = false;
+                    }
+                } else {
+                    if (c == '{') {
+                        depth++;
+                    } else if (c == '}') {
+                        depth--;
+                    } else if (c == '"') {
+                        inString = true;
+                    } else if (c == '\n') {
+                        addLine(offset);
+                    }
+                    if (depth > 0) {
+                        break;
+                    }
+                }
+                offset--;
+            }
+            return offset;
+        }
+    }
